#[verifier::inline]
pub open spec fn spec_result_transpose<T, E>(
    result: core::result::Result<core::option::Option<T>, E>,
) -> core::option::Option<core::result::Result<T, E>> {
    match result {
        core::result::Result::Ok(core::option::Option::Some(value)) => {
            core::option::Option::Some(core::result::Result::Ok(value))
        },
        core::result::Result::Ok(core::option::Option::None) => {
            core::option::Option::None
        },
        core::result::Result::Err(error) => {
            core::option::Option::Some(core::result::Result::Err(error))
        },
    }
}

#[verifier::when_used_as_spec(spec_result_transpose)]
