        match result {
            core::result::Result::Ok(index) => {
                &&& slice@.len() > index
                &&& slice@[index as int].cmp_spec(x) == core::cmp::Ordering::Equal
                &&& forall|i: int| #![auto] i > index as int && slice@.len() > i ==>
                    slice@[i].cmp_spec(x) == core::cmp::Ordering::Greater
            },
            core::result::Result::Err(index) => {
                &&& slice@.len() >= index
                &&& forall|i: int| #![auto] i >= 0 && index as int > i ==>
                    slice@[i].cmp_spec(x) == core::cmp::Ordering::Less
                &&& forall|i: int| #![auto] i >= index as int && slice@.len() > i ==>
                    slice@[i].cmp_spec(x) == core::cmp::Ordering::Greater
            },
        },
;

