    ensures
        res == (
            s.spec_bytes().len() == other.spec_bytes().len()
            && forall|i: int| i >= 0 && s.spec_bytes().len() > i ==>
                (if s.spec_bytes()[i] >= 65 && 90 >= s.spec_bytes()[i] {
                    s.spec_bytes()[i] as int + 32
                } else {
                    s.spec_bytes()[i] as int
                }) == (if other.spec_bytes()[i] >= 65 && 90 >= other.spec_bytes()[i] {
                    other.spec_bytes()[i] as int + 32
                } else {
                    other.spec_bytes()[i] as int
                })
        ),
;

ensures:
match result {
            Some((key, value)) => {
                &&& contains_borrowed_key(old(m)@, k)
                &&& sets_borrowed_key_to_key(old(m)@.dom(), k, &key)
                &&& old(m)@.contains_key(key)
                &&& old(m)@[key] == value
                &&& final(m)@ == old(m)@.remove(key)
            },
            None => {
                &&& !contains_borrowed_key(old(m)@, k)
                &&& final(m)@ == old(m)@
            },
        }

sets_differ_by_borrowed_key(old(m)@, final(m)@, value); match result {
            Some(v) => {
                &&& set_contains_borrowed_key(old(m)@, value)
                &&& sets_borrowed_key_to_key(old(m)@, value, &v)
                &&& old(m)@.contains(v)
                &&& final(m)@ == old(m)@.remove(v)
            },
            None => {
                &&& !set_contains_borrowed_key(old(m)@, value)
                &&& final(m)@ == old(m)@
            },
        }
